security = value['security']
canCreate = False
canEdit = False
if security['userCRUD'] is not None and security['userId'] is not None:
	if security['userCRUD']['isGatewayAdmin'] or security['userCRUD']['editOperations']['enabled']: 
		canCreate = True if len(value['modeEvents'] or []) > 0 else False
		canEdit = True if len(value['perfEvents'] or []) > 0 else False

return {"canCreate": canCreate, "canDelete": canEdit, "canRead": True, "canUpdate": canEdit}

