self.clearModeEvents()

value = self.view.custom.filter
assetPath = value['assetPath'] or None
if assetPath is None: return []

self.view.custom.info = {"showBar": True, "text": "Getting mode events", "type": "INFO"}	

paramsDict = {'assetPath': assetPath + '%', 'startDate': value['startDate'], 'endDate': value['endDate']}
self.view.custom.shiftProductionEvents.data = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.event.getAssetPerformanceEventsByShift(paramsDict))

self.clearModeEventSelection()

self.view.custom.info = {"showBar": False, "text": "", "type": "INFO"}	

return

retVal, msg = system.kanoa.event.deletePerformanceEvent(self.view.custom.performanceEvents.selection.data[0].performanceEventId, self.view.custom.security.userId)

self.getPerfEvents()

if msg: system.perspective.sendMessage('showFailerToast', {'message': "%s"%msg})
else: system.perspective.sendMessage('showSuccefulToast', {'message': "Reason saved"})



return

if edit: 
	selection = self.view.custom.performanceEvents.selection.data[0]
	params = {'value': {
					'startDate': system.date.fromMillis(selection['millisStart']),
					'endDate': system.date.fromMillis(selection['millisEnd']),
					"lossTimeMins": selection['value'],
					"modeEventId": selection['modeEventId'],
					"performanceStateId": selection['performanceStateId'],
					"performanceEventId": selection['performanceEventId'],
					"note": selection['note']
			}}
else:
	selection = self.view.custom.shiftProductionEvents.selection.data[0]
	params = {'value': {
					'startDate': system.date.fromMillis(selection['millisStart']),
					'endDate': system.date.fromMillis(selection['millisEnd']),
					"lossTimeMins": selection['lossTimeMins'],
					"modeEventId": selection['modeEventId'],
					"performanceStateId": None,
					"performanceEventId": None,
					"note": None
			}}
system.perspective.print(params)
system.perspective.openPopup("perfReasonEditor", 'kanoa/mes/asset/counts/perfReasonEditor', params, resizable=True, draggable=True, showCloseIcon=True)

return
